/**
 * 负责四族原生／学习死亡枪的数据创建、原槽安装、武装、捕获复验和库存消费。
 * 输入为原角色、原学习对象与晚取查询；输出保留同一槽／枪引用和原每次 hook 的捕获表。
 * 原生安装不克隆、不冻库存；学习模板仅创建自己的全新枪，已有整学习数据的复制仍由各族安装 owner 执行。
 * 本 owner 安装两个原生槽并写原枪字段，原体、生命、死因及请求许可仍在结算／具体权威复验；只读类型不是权限屏障。
 * 猎魔板子先捕获原审计库存，支付仍由同一权威执行；setter／编码或后续发表失败均不退款。
 */
import type {
  HunterState,
  HunterReadState,
  WolfKingState,
  WolfKingReadState,
  MechanicalReadState as MechanicalState,
  MechanicalReadLearning as MechanicalLearning,
  MechanicalReadSkill as MechanicalSkill,
  MechanicalReadState,
  AwakenedReadState as AwakenedState,
  AwakenedReadLearning as AwakenedLearning,
  AwakenedReadSkill as AwakenedSkill,
  AwakenedReadState,
} from "@ai-werewolf-arena/game-contract";
import { Camp, Role } from "../../../core/domain/model";
import type { RoleComponent } from "../../../core/domain/components/role";
import type { World } from "../../../core/domain/world";
import type { RoleInitContext } from "./contracts";
import type { openDemonHunterStockFrame } from "./demon_hunter/native-gun-ports";

/** 创建仍逐次读取原配置 getter，不缓存 boardConfig／policy；分支保持原字段可选性。 */
export function createHunterState(ctx: Pick<RoleInitContext, "boardConfig">): HunterState {
  return {
    canShoot: true,
    ...(ctx.boardConfig?.hunter?.deathActionPolicy === "awa_knife_or_exile_v1"
      ? { deathActionPolicy: ctx.boardConfig.hunter.deathActionPolicy }
      : {}),
  };
}
export function createWolfKingState(ctx: Pick<RoleInitContext, "boardConfig">): WolfKingState {
  return {
    canShoot: true,
    ...(ctx.boardConfig?.wolfKing?.deathActionPolicy !== undefined &&
    ctx.boardConfig.wolfKing.deathActionPolicy !== "awa_qualified_sources_v1"
      ? { deathActionPolicy: ctx.boardConfig.wolfKing.deathActionPolicy }
      : {}),
  };
}

/** get 仍可调用原槽 getter；set 原左值赋入同对象，不新增 schema 或 descriptor 拒绝。 */
export function setHunterState(roleComp: RoleComponent, state: HunterState): HunterReadState {
  (roleComp.privateState as { hunter: HunterState })["hunter"] = state;
  return state;
}

export function getHunterState(roleComp: RoleComponent): HunterReadState | undefined {
  return (roleComp.privateState as { readonly hunter?: unknown })["hunter"] as
    HunterReadState | undefined;
}

export function setWolfKingState(roleComp: RoleComponent, state: WolfKingState): WolfKingReadState {
  (roleComp.privateState as { wolf_king: WolfKingState })["wolf_king"] = state;
  return state;
}

export function getWolfKingState(roleComp: RoleComponent): WolfKingReadState | undefined {
  return (roleComp.privateState as { readonly wolf_king?: unknown })["wolf_king"] as
    WolfKingReadState | undefined;
}

export type LearnedNativeGun = Extract<MechanicalSkill, { kind: "hunter" }>;
/** 学习得到新满库存模板，不从目标玩家复制已花费资源或原体许可。 */
export function createLearnedNativeGun(): { kind: "hunter"; canShoot: boolean; armed: boolean } {
  return { kind: "hunter", canShoot: true, armed: false };
}
/** 实际夜／激活检查仍由本族调用方先完成；只在原赋值点武装同一枪，不补偿其他字段。 */
function armLearnedNativeGun(gun: LearnedNativeGun): void {
  (gun as { armed: boolean }).armed = true;
}

/** 机械枪必须进入实际 ready 夜；保持 kind→ready→原 skill 左值读取，不因模式或查询补武装。 */
export function armMechanicalNativeGun(learned: MechanicalReadLearning, day: number): void {
  if (learned.skill.kind === "hunter" && day >= learned.readyOnNight)
    armLearnedNativeGun(learned.skill);
}
/** 觉醒枪仅在原整次激活通过后武装；activationNight／activeFromNight 仍在其后原点更新。 */
export function armAwakenedNativeGun(learned: AwakenedReadLearning): void {
  if (learned.skill.kind === "hunter") armLearnedNativeGun(learned.skill);
}

/** 生产每次 hook 独立持有原捕获表；这里不另验 World，换学习／原枪后返回 undefined。 */
export function createMechanicalGunReader(runtime: {
  readonly getMechanicalState: (role: RoleComponent | undefined) => MechanicalReadState | undefined;
}): (role: RoleComponent) => LearnedNativeGun | undefined {
  const owners = new Map<
    RoleComponent,
    {
      state: MechanicalState;
      learning: MechanicalLearning;
      gun: Extract<MechanicalSkill, { kind: "hunter" }>;
    }
  >();
  return (role) => {
    const query = runtime.getMechanicalState;
    const state = query(role),
      learning = state?.learned,
      skill = learning?.skill;
    if (role.camp !== Camp.Wolf || !state || !learning || skill?.kind !== "hunter" || !skill.armed)
      return undefined;
    const prior = owners.get(role);
    if (prior && (state !== prior.state || learning !== prior.learning || skill !== prior.gun))
      return undefined;
    if (!prior) owners.set(role, { state, learning, gun: skill });
    return skill;
  };
}

/** 生产每次 hook 独立持有原捕获表；这里不另验 World，换学习／原枪后返回 undefined。 */
export function createAwakenedGunReader(runtime: {
  readonly getAwakenedState: (role: RoleComponent | undefined) => AwakenedReadState | undefined;
}): (role: RoleComponent) => LearnedNativeGun | undefined {
  const owners = new Map<
    RoleComponent,
    {
      state: AwakenedState;
      learned: AwakenedLearning;
      gun: Extract<AwakenedSkill, { kind: "hunter" }>;
      targetId: number;
      role: AwakenedLearning["role"];
      day: number;
      activationNight: number;
      activeFromNight: number;
    }
  >();
  return (role) => {
    const query = runtime.getAwakenedState;
    const state = query(role),
      learned = state?.learned,
      gun = learned?.skill;
    if (
      role.camp !== Camp.Wolf ||
      !state ||
      !learned ||
      learned.role !== Role.Hunter ||
      learned.activationNight === null ||
      learned.activeFromNight === null ||
      gun?.kind !== "hunter" ||
      !gun.armed
    )
      return undefined;
    const prior = owners.get(role);
    if (
      prior &&
      (state !== prior.state ||
        learned !== prior.learned ||
        gun !== prior.gun ||
        learned.targetId !== prior.targetId ||
        learned.role !== prior.role ||
        learned.day !== prior.day ||
        learned.activationNight !== prior.activationNight ||
        learned.activeFromNight !== prior.activeFromNight)
    )
      return undefined;
    if (!prior)
      owners.set(role, {
        state,
        learned,
        gun,
        targetId: learned.targetId,
        role: learned.role,
        day: learned.day,
        activationNight: learned.activationNight,
        activeFromNight: learned.activeFromNight,
      });
    return gun;
  };
}

/** 晚取原猎魔命令；非 Hunter 分支不读命令，类型引用不会初始化 authority。 */
export interface NativeDeathGunStockQueries {
  readonly openHunterStock?: typeof openDemonHunterStockFrame;
}
export function captureNativeGunStock(
  kind: Role,
  queries: NativeDeathGunStockQueries,
  world: World,
  actorId: number,
  state: object,
): ReturnType<typeof openDemonHunterStockFrame> {
  if (kind !== "hunter") return null;
  const command = queries.openHunterStock!;
  return command(world, actorId, state);
}
/** 付款不补资格：原 stock 自验并写审计；普通分支只写原 canShoot。失败保原写入前缀。 */
export function consumeNativeDeathGun(
  state: { readonly canShoot: boolean },
  stock: ReturnType<typeof openDemonHunterStockFrame>,
): void {
  if (stock) stock.consume();
  else (state as { canShoot: boolean }).canShoot = false;
}

/**
 * 单元测试负责四族原生／学习枪的数据身份、晚查询及结算付款失败前缀。
 * 输入为真实 Role／Alive／World、手写访问器与原学习函数；输出为独立字面轨迹、引用和拒绝。
 * 原 getter／setter 故障对象只模拟调用边界，不扩生产 schema；不运行对局、模型或从结算算法推导预期。
 */
import { expect, test } from "bun:test";
import { Camp, Role, Phase } from "@ai-werewolf-arena/game-contract";
import type { GameEvent } from "@ai-werewolf-arena/game-contract/events";
import { createRoleComponent } from "../../../src/core/domain/components/role";
import { createAliveComponent } from "../../../src/core/domain/components/alive";
import { COMPONENT } from "../../../src/core/domain/components/names";
import { DeathCause } from "../../../src/core/domain/deaths";
import { World } from "../../../src/core/domain/world";
import type { RoleInitContext } from "../../../src/game/mechanisms/roles/contracts";
import {
  createHunterState,
  createWolfKingState,
  setHunterState,
  getHunterState,
  createLearnedNativeGun,
  createMechanicalGunReader,
  createAwakenedGunReader,
  captureNativeGunStock,
} from "../../../src/game/mechanisms/roles/native-death-gun-resources";
import { resolveNativeDeathShots } from "../../../src/game/mechanisms/roles/native-death-shot-settlement";
import {
  freshMechanicalState,
  setMechanicalState,
  getMechanicalState,
  learnMechanicalRole,
  advanceMechanicalNight,
} from "../../../src/game/mechanisms/roles/mechanical_wolf/state";
import {
  freshAwakenedState,
  setAwakenedState,
  getAwakenedState,
  learnAwakenedRole,
  activateAwakenedLearning,
} from "../../../src/game/mechanisms/roles/awakened_hidden_wolf/state";

function shotWorld() {
  const world = new World("en"),
    actor = world.createEntity(),
    target = world.createEntity();
  const role = createRoleComponent(Role.Hunter, Camp.Good);
  world.addComponent(actor, COMPONENT.Role, role);
  world.addComponent(actor, COMPONENT.Alive, createAliveComponent(false));
  world.addComponent(target, COMPONENT.Role, createRoleComponent(Role.Villager, Camp.Good));
  world.addComponent(target, COMPONENT.Alive, createAliveComponent(true));
  return { world, actor, target, role };
}

test("原生创建保配置重复读取、可选政策及同引用安装，不新增shape拒绝", () => {
  const trace: string[] = [];
  // 仅构造这些原工厂实际读取的字段；这是内存 getter 输入，不是新的公共板子接受政策。
  const ctx = {
    get boardConfig() {
      trace.push("board");
      return {
        get hunter() {
          trace.push("hunter");
          return {
            get deathActionPolicy() {
              trace.push("policy");
              return "awa_knife_or_exile_v1";
            },
          };
        },
      };
    },
  } as unknown as Pick<RoleInitContext, "boardConfig">;
  const state = createHunterState(ctx),
    role = createRoleComponent(Role.Hunter, Camp.Good);
  expect(trace).toEqual(["board", "hunter", "policy", "board", "hunter", "policy"]);
  expect(state).toEqual({ canShoot: true, deathActionPolicy: "awa_knife_or_exile_v1" });
  expect(setHunterState(role, state)).toBe(state);
  expect(getHunterState(role)).toBe(state);
  expect(createWolfKingState({})).toEqual({ canShoot: true });
  expect(Object.isFrozen(state)).toBe(false);
  const first = createLearnedNativeGun(),
    second = createLearnedNativeGun();
  expect(first).toEqual({ kind: "hunter", canShoot: true, armed: false });
  expect(first).not.toBe(second);
});

test("学习枪每次hook独立捕获、查询晚裸调用，机械和觉醒保各自复验字段", () => {
  const mechanical = createRoleComponent(Role.MechanicalWolf, Camp.Wolf);
  const ms = setMechanicalState(mechanical, freshMechanicalState());
  learnMechanicalRole(ms, 3, Role.Hunter, 1);
  advanceMechanicalNight(ms, 2);
  const trace: unknown[] = [];
  const reader = createMechanicalGunReader({
    get getMechanicalState() {
      trace.push("lookup");
      return function (this: unknown, role) {
        trace.push(this);
        return getMechanicalState(role);
      };
    },
  });
  expect(trace).toEqual([]);
  const gun = ms.learned!.skill;
  expect(reader(mechanical)).toBe(gun);
  expect(trace).toEqual(["lookup", undefined]);
  (ms as { learned: typeof ms.learned }).learned = { ...ms.learned! };
  expect(reader(mechanical)).toBeUndefined();
  expect(createMechanicalGunReader({ getMechanicalState })(mechanical)).toBe(gun);
  const awakened = createRoleComponent(Role.AwakenedHiddenWolf, Camp.Wolf);
  const as = setAwakenedState(awakened, freshAwakenedState());
  learnAwakenedRole(as, 3, Role.Hunter, 1);
  activateAwakenedLearning(as, 1);
  const awReader = createAwakenedGunReader({ getAwakenedState });
  expect(awReader(awakened)).toBe(as.learned!.skill);
  (as.learned as { activationNight: number | null }).activationNight = 2;
  expect(awReader(awakened)).toBeUndefined();
  expect(gun).toEqual({ kind: "hunter", canShoot: true, armed: true });
});

test("审计stock在sources之前晚捕获，await后stock撤权先于角色复验", async () => {
  const f = shotWorld(),
    state = setHunterState(f.role, { canShoot: true }),
    events: GameEvent[] = [];
  const trace: unknown[] = [],
    failure = new Error("demon_hunter_native_hunter_stock_revoked");
  const sources = {
    get [f.actor]() {
      trace.push("sources");
      return [DeathCause.Exile];
    },
  };
  const stock = {
    consume() {
      trace.push("consume");
    },
    isCurrent() {
      trace.push("stock.current");
      return false;
    },
  };
  const rules = {
    role: Role.Hunter,
    state: getHunterState,
    permits: () => true,
    get openHunterStock() {
      trace.push("command.lookup");
      return function (this: unknown, ...args: unknown[]) {
        trace.push(this, "command.call");
        expect(args).toEqual([f.world, f.actor, state]);
        return stock;
      };
    },
    shotEvent: () => ({
      timestamp: 1,
      type: "hunter_shot",
      payload: { hunterId: f.actor, targetId: f.target },
    }),
  };
  await expect(
    resolveNativeDeathShots(
      f.world,
      [f.actor],
      sources,
      async () => {
        trace.push("choose");
        Object.defineProperty(f.role, "privateState", {
          get() {
            throw new Error("must_not_revalidate_after_stock");
          },
        });
        return { kind: "invalid" };
      },
      events,
      rules,
    ),
  ).rejects.toThrow(failure);
  expect(trace).toEqual([
    "command.lookup",
    undefined,
    "command.call",
    "sources",
    "choose",
    "stock.current",
  ]);
  expect(events).toEqual([]);
  expect(state.canShoot).toBe(true);
  const world = new World("en");
  expect(
    captureNativeGunStock(
      Role.WolfKing,
      {
        get openHunterStock(): never {
          throw new Error("must_not_lookup_hunter_command");
        },
      },
      world,
      1,
      state,
    ),
  ).toBeNull();
});

test("有效命中先付款再取保护方法，保护lookup失败不退款或产生提案事实", async () => {
  const f = shotWorld(),
    trace: string[] = [],
    events: GameEvent[] = [];
  let canShoot = true;
  const state = setHunterState(f.role, {
    get canShoot() {
      return canShoot;
    },
    set canShoot(value: boolean) {
      trace.push("consume");
      canShoot = value;
    },
  });
  const permit = f.world.openDeathAction(f.actor, "shoot", Phase.Voting, 2);
  const failure = new Error("literal_protection_lookup_failed");
  try {
    await expect(
      resolveNativeDeathShots(
        f.world,
        [f.actor],
        { [f.actor]: [DeathCause.Exile] },
        async () => ({ kind: "shot", targetId: f.target, deathActionId: permit.id }),
        events,
        {
          role: Role.Hunter,
          state: getHunterState,
          permits: () => true,
          openHunterStock: () => null,
          shotEvent: () => {
            trace.push("event");
            return {
              timestamp: 1,
              type: "hunter_shot",
              payload: { hunterId: f.actor, targetId: f.target },
            };
          },
        },
        {
          nightEffect: true,
          get blocksNightShot(): never {
            trace.push("protection");
            throw failure;
          },
        },
      ),
    ).rejects.toThrow(failure);
  } finally {
    permit.close();
  }
  expect(trace).toEqual(["consume", "protection"]);
  expect(state.canShoot).toBe(false);
  expect(events).toEqual([]);
  expect(f.world.getComponent(f.target, COMPONENT.Alive)!.alive).toBe(true);
  expect(f.world.activeDeathActionCount).toBe(0);
});
